# --------------------------------------------------
# 0. CONFIGURACIÓN DE CODIFICACIÓN
# --------------------------------------------------
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# --------------------------------------------------
# 1. FUNCIÓN PARA OCULTAR LA CONSOLA
# --------------------------------------------------
$ShowWindowAsync = Add-Type -MemberDefinition @"
    [DllImport("user32.dll")]
    public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
"@ -Name "Win32ShowWindowAsync" -Namespace Win32Functions -PassThru

function Hide-Console {
    $consolePtr = (Get-Process -Id $PID).MainWindowHandle
    $ShowWindowAsync::ShowWindowAsync($consolePtr, 0) # 0 = SW_HIDE
}

# --------------------------------------------------
# 2. LÓGICA DE HARDENING 
# --------------------------------------------------
function Start-Hardening-GUI {
    param($logBox)

    $steps = @(
        @{ n = "Activando Firewall de Windows"; c = { Set-NetFirewallProfile -Profile Domain,Public,Private -Enabled True } },
        @{ n = "Bloqueando puertos criticos (21,23,445...)"; c = { 21,23,69,135,137,138,139,445 | ForEach-Object { New-NetFirewallRule -DisplayName "Block_$_" -Direction Inbound -Protocol TCP -LocalPort $_ -Action Block -ErrorAction SilentlyContinue } } },
        @{ n = "Deshabilitando protocolo SMBv1"; c = { Disable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -NoRestart } },
        @{ n = "Forzando firma digital en SMB"; c = { Set-SmbServerConfiguration -RequireSecuritySignature $true -Force } },
        @{ n = "Deshabilitando NetBIOS sobre TCP/IP"; c = { Get-WmiObject Win32_NetworkAdapterConfiguration | Where-Object {$_.IPEnabled} | ForEach-Object {$_.SetTcpipNetbios(2)} } },
        @{ n = "Deshabilitando resolucion LLMNR"; c = { New-Item "HKLM:\Software\Policies\Microsoft\Windows NT\DNSClient" -Force; Set-ItemProperty "HKLM:\Software\Policies\Microsoft\Windows NT\DNSClient" -Name EnableMulticast -Value 0 } },
        @{ n = "Reduciendo Telemetria"; c = { New-Item "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Force; Set-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name AllowTelemetry -Value 0 } },
        @{ n = "Deshabilitando WDigest"; c = { Set-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest" -Name UseLogonCredential -Value 0 } },
        @{ n = "Configurando Control de Cuentas (UAC)"; c = { Set-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" -Name EnableLUA -Value 1 } },
        @{ n = "Deshabilitando AutoRun"; c = { New-Item "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" -Force; Set-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer" -Name NoDriveTypeAutoRun -Value 255 } },
        @{ n = "Activando SmartScreen"; c = { Set-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer" -Name SmartScreenEnabled -Value "RequireAdmin" } },
        @{ n = "Deshabilitando WinRM y Registro Remoto"; c = { "WinRM", "RemoteRegistry" | ForEach-Object { Stop-Service $_ -Force -ErrorAction SilentlyContinue; Set-Service $_ -StartupType Disabled } } },
        @{ n = "Habilitando Auditoria de PowerShell"; c = { New-Item "HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging" -Force; Set-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging" -Name EnableScriptBlockLogging -Value 1 } },
        @{ n = "Fortaleciendo Microsoft Defender"; c = { Set-MpPreference -DisableRealtimeMonitoring $false -MAPSReporting Advanced } },
        @{ n = "Activando Proteccion de Red y Ransomware"; c = { Set-MpPreference -EnableNetworkProtection Enabled -EnableControlledFolderAccess Enabled } },
        @{ n = "Deshabilitando PowerShell v2"; c = { Disable-WindowsOptionalFeature -Online -FeatureName MicrosoftWindowsPowerShellV2 -NoRestart } },
        @{ n = "Habilitando TLS 1.2"; c = { New-Item "HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\SCHANNEL\Protocols\TLS 1.2\Server" -Force; Set-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\SCHANNEL\Protocols\TLS 1.2\Server" -Name Enabled -Value 1 } },
        @{ n = "Configurando politicas de contrasena"; c = { net accounts /minpwlen:12 /maxpwage:60 /lockoutthreshold:5 } },
        @{ n = "Habilitando Credential Guard y VBS"; c = { Set-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" -Name "EnableVirtualizationBasedSecurity" -Value 1 -Force; Set-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\Lsa" -Name "LsaCfgFlags" -Value 1 -Force } },
        @{ n = "Bloqueando Autenticacion Insegura Guest (SMB)"; c = { $lanman = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\LanmanWorkstation"; New-Item $lanman -Force; Set-ItemProperty $lanman -Name "AllowInsecureGuestAuth" -Value 0 } },
        @{ n = "Aplicando Attack Surface Reduction (FULL 14)"; c = { $asrRules = @("be9ba2d9-539a-4d17-ba2d-1644769062a5", "d4f940ab-401b-4efc-aadc-ad5f3c50688a", "3b576861-7eb4-4d5d-b359-ba2386660fdd", "75668c1f-73b5-4cf0-bb93-3ec93f8adf5d", "d1e49f24-3315-4321-8399-95f6d8146d61", "56a863a9-875e-4185-98a7-b882c64b5ce5", "92e97fa1-2eed-4e4e-ad5a-17c641a46442", "b2b3f03d-2e65-471e-8536-bb8118474675", "9e6cde19-a30d-4609-b204-203102a162f3", "d3e037e1-3eb1-4495-b900-3520afc304e5", "26190d00-5950-4c10-8b00-227be261123e", "01443f2c-9615-44a0-9b7e-27bcec6e99a7", "c1db545a-bcd1-4bc0-a241-d715d352b39c", "e6db77e5-3df2-4cf1-b95a-636979351e5b"); $asrRules | ForEach-Object { Add-MpPreference -AttackSurfaceReductionRules_Ids $_ -AttackSurfaceReductionRules_Actions Enabled -ErrorAction SilentlyContinue } } },
        @{ n = "Auditoria Forense (CMD Line)"; c = { auditpol /set /subcategory:"Process Creation" /success:enable /failure:enable; $auditPath = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System\Audit"; New-Item $auditPath -Force; Set-ItemProperty $auditPath -Name "ProcessCreationIncludeCmdLine_Enabled" -Value 1 } },
        @{ n = "Endurecimiento de RDP (NLA Fuerte)"; c = { $rdpPath = "HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp"; Set-ItemProperty $rdpPath -Name "UserAuthentication" -Value 1; Set-ItemProperty $rdpPath -Name "MinEncryptionLevel" -Value 3 } },
        @{ n = "Bloqueando ejecucion en %TEMP%"; c = { $tempPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Safer\CodeIdentifiers\0\Paths\{temp_block}"; New-Item $tempPath -Force; Set-ItemProperty $tempPath -Name "SaferFlags" -Value 0 } }
    )

    foreach ($step in $steps) {
        $logBox.AppendText("[+] $($step.n.PadRight(45, "."))")
        try {
            & $step.c | Out-Null
            $logBox.AppendText(" [ OK ]`r`n")
        } catch {
            $logBox.AppendText(" [ FAIL ]`r`n")
        }
        $logBox.SelectionStart = $logBox.Text.Length
        $logBox.ScrollToCaret()
        $logBox.Refresh()
    }

    $logBox.AppendText("`r`n--- CONFIGURACIONES ADICIONALES ---`r`n")
    
    $askRDP = [System.Windows.Forms.MessageBox]::Show("¿Deseas DESACTIVAR RDP (Escritorio Remoto)?", "NetBrix", "YesNo", "Question")
    if ($askRDP -eq "Yes") {
        $logBox.AppendText("[>] Desactivando RDP...")
        Set-ItemProperty "HKLM:\System\CurrentControlSet\Control\Terminal Server" -Name "fDenyTSConnections" -Value 1
        Disable-NetFirewallRule -DisplayGroup "Remote Desktop" -ErrorAction SilentlyContinue
        $logBox.AppendText(" HECHO`r`n")
    }

    $askIPv6 = [System.Windows.Forms.MessageBox]::Show( "¿Deseas DESACTIVAR IPv6 via Registro?", "NetBrix Security", "YesNo", "Question")
    if ($askIPv6 -eq "Yes") {
        $logBox.AppendText("[>] Deshabilitando IPv6 globalmente...")
        $ipv6Path = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters"
        if (!(Test-Path $ipv6Path)) { New-Item -Path $ipv6Path -Force | Out-Null }
        Set-ItemProperty -Path $ipv6Path -Name "DisabledComponents" -Value 0xFF -Type DWord -Force
        $logBox.AppendText(" [ OK ]`r`n")
    }
    
    $askSFC = [System.Windows.Forms.MessageBox]::Show("¿Ejecutar SFC /scannow?", "NetBrix", "YesNo", "Warning")
    if ($askSFC -eq "Yes") {
        $logBox.AppendText("[>] Ejecutando SFC...`r`n")
        sfc /scannow | Out-Null
        $logBox.AppendText("[!] SFC finalizado.`r`n")
    }

    $askDefender = [System.Windows.Forms.MessageBox]::Show( "¿Analisis COMPLETO de Defender?", "NetBrix", "YesNo", "Question")
    if ($askDefender -eq "Yes") {
        $logBox.AppendText("[>] Iniciando Análisis de Defender...`r`n")
        Start-MpScan -ScanType FullScan
        $logBox.AppendText("[!] Análisis completado.`r`n")
    }
    
    $logBox.AppendText("`r`n==================================================`r`n")
    $logBox.AppendText(" PROCESO DE HARDENING FINALIZADO`r`n")
    $logBox.AppendText("Desarrollado por: Brixciel Vergara Morales") 
    $logBox.AppendText("`r`n==================================================`r`n")
}

# --------------------------------------------------
# 3. CONSTRUCCIÓN DE LA INTERFAZ
# --------------------------------------------------
Hide-Console

$form = New-Object System.Windows.Forms.Form
$form.Text = "NetBrix Security Hardening - v2.0"
$form.Size = New-Object System.Drawing.Size(700,550)
$form.StartPosition = "CenterScreen"
$form.BackColor = "#020617" 
$form.FormBorderStyle = "FixedDialog"
$form.MaximizeBox = $false

# --- INCRUSTACIÓN DE IMAGEN (BASE64) ---
$base64Image = ""

if ($base64Image = "") {
    try {
        $imageBytes = [Convert]::FromBase64String($base64Image)
        $ms = New-Object IO.MemoryStream($imageBytes, 0, $imageBytes.Length)
        $img = [System.Drawing.Image]::FromStream($ms)
        $form.BackgroundImage = $img
        $form.BackgroundImageLayout = "Stretch"
    } catch {
        # Si falla la carga Base64, intenta cargar el archivo local como respaldo
        $imagePath = Join-Path $PSScriptRoot "fondo_red.jpg" 
        if (Test-Path $imagePath) {
            $img = [System.Drawing.Image]::FromFile($imagePath)
            $form.BackgroundImage = $img
            $form.BackgroundImageLayout = "Stretch"
        }
    }
} else {
    # Respaldo por si olvidas pegar el código Base64
    $imagePath = Join-Path $PSScriptRoot "fondo_red.jpg" 
    if (Test-Path $imagePath) {
        $img = [System.Drawing.Image]::FromFile($imagePath)
        $form.BackgroundImage = $img
        $form.BackgroundImageLayout = "Stretch"
    }
}

$title = New-Object System.Windows.Forms.Label
$title.Text = "WINDOWS SECURITY HARDENING SYSTEM"
$title.ForeColor = "#FFFFFF"  
$title.BackColor = "Transparent"
$title.Font = New-Object System.Drawing.Font("Segoe UI",16,[System.Drawing.FontStyle]::Bold)
$title.TextAlign = "MiddleCenter"
$title.Dock = "Top"
$title.Height = 60

# Créditos resaltados
$credits = New-Object System.Windows.Forms.Label
$credits.Text = "Desarrollado por: Brixciel Vergara Morales"
$credits.ForeColor = "#FFFFFF"  
$credits.BackColor = "Transparent"
$credits.Font = New-Object System.Drawing.Font("Segoe UI", 12, [System.Drawing.FontStyle]::Bold)
$credits.TextAlign = "MiddleCenter"
$credits.Location = New-Object System.Drawing.Point(0, 60) 
$credits.Width = 700

# Caja de Log: FONDO NEGRO Y LETRAS VERDES
$log = New-Object System.Windows.Forms.TextBox
$log.Multiline = $true
$log.ReadOnly = $true
$log.Size = New-Object System.Drawing.Size(630,280)
$log.Location = New-Object System.Drawing.Point(25,190)
$log.BackColor = "#000000" 
$log.ForeColor = "#00FF00" 
$log.Font = New-Object System.Drawing.Font("Consolas",10)
$log.BorderStyle = "FixedSingle"
$log.ScrollBars = "Vertical"

$button = New-Object System.Windows.Forms.Button
$button.Text = "INICIAR PROCESO DE HARDENING"
$button.Size = New-Object System.Drawing.Size(320,55)
$button.Location = New-Object System.Drawing.Point(185,110)
$button.BackColor = "#0891B2"
$button.ForeColor = "White"
$button.FlatStyle = "Flat"
$button.FlatAppearance.BorderSize = 2
$button.FlatAppearance.BorderColor = "#22D3EE"
$button.Cursor = "Hand"
$button.Font = New-Object System.Drawing.Font("Segoe UI",11,[System.Drawing.FontStyle]::Bold)

$button.Add_Click({
    $button.Enabled = $false
    $button.Text = "EJECUTANDO..."
    $log.Clear()
    $log.AppendText("Iniciando protocolos...`r`n")
    Start-Hardening-GUI -logBox $log
    $button.Enabled = $true
    $button.Text = "PROCESO COMPLETADO"
})

$form.Controls.Add($title)
$form.Controls.Add($credits)
$form.Controls.Add($button)
$form.Controls.Add($log)

$form.ShowDialog()